package com.bank.stats;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class SummaryStatsTest {

    @Test void summaryStatisticsInOnePass() {
        IntSummaryStatistics stats = IntStream.of(10, 20, 30, 40, 50).summaryStatistics();
        assertThat(stats.getCount()).isEqualTo(5);
        assertThat(stats.getSum()).isEqualTo(150);
        assertThat(stats.getMin()).isEqualTo(10);
        assertThat(stats.getMax()).isEqualTo(50);
        assertThat(stats.getAverage()).isEqualTo(30.0);
    }

    @Test void emptySummaryStatistics() {
        IntSummaryStatistics stats = IntStream.empty().summaryStatistics();
        assertThat(stats.getCount()).isZero();
        assertThat(stats.getMin()).isEqualTo(Integer.MAX_VALUE);  // convention for empty
        assertThat(stats.getMax()).isEqualTo(Integer.MIN_VALUE);
    }

    @Test void asDownstreamCollector() {
        record Emp(String dept, int age) {}
        var emps = List.of(new Emp("A", 30), new Emp("A", 40), new Emp("B", 25));
        Map<String, IntSummaryStatistics> byDept = emps.stream()
            .collect(Collectors.groupingBy(Emp::dept, Collectors.summarizingInt(Emp::age)));
        assertThat(byDept.get("A").getAverage()).isEqualTo(35.0);
        assertThat(byDept.get("B").getCount()).isEqualTo(1);
    }
}
