// File: src/test/java/com/bank/java8/SummaryStatsTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.IntSummaryStatistics;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class SummaryStatsTest {

    @Test
    void allAggregatesInOnePass() {
        List<Integer> balances = List.of(1000, 5000, 2000, 8000);

        IntSummaryStatistics stats = balances.stream()
            .mapToInt(Integer::intValue)
            .summaryStatistics();

        assertThat(stats.getCount()).isEqualTo(4);
        assertThat(stats.getSum()).isEqualTo(16000);
        assertThat(stats.getMin()).isEqualTo(1000);
        assertThat(stats.getMax()).isEqualTo(8000);
        assertThat(stats.getAverage()).isEqualTo(4000.0);
    }
}
